border:1px solid #dce3ed;border-radius:8px;background:white;color:inherit;width:100%}.filters select{width:auto}label{display:block;font-size:13px;font-weight:650;margin:18px 0 7px}textarea{resize:vertical}small{color:#738096}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;color:#738096;font-size:11px;letter-spacing:.6px;text-transform:uppercase}td,th{padding:16px 10px;border-bottom:1px solid #edf0f5}td:first-child{min-width:175px}td small{display:block}.badge{display:inline-block;padding:4px 9px;border-radius:16px;background:#e8f7ee;color:#21794b;white-space:nowrap}.inactive{background:#f0f2f5;color:#697587}.actions{display:flex;gap:10px;align-items:center;white-space:nowrap}.actions button{font-size:12px;padding:6px 9px}.notice{padding:14px 18px;border-radius:10px;background:#e8f7ee;color:#21794b;margin:18px 0}.errors{background:#fff0f0;color:#a32935;padding:16px 32px;border-radius:10px}.pagination{display:flex;justify-content:space-between;align-items:center;margin-top:20px;font-size:13px}.helper{background:#f4f7fb;padding:14px;border-radius:9px;font-size:13px;color:#738096;margin-top:22px}.empty{text-align:center;padding:38px;color:#738096}.form-actions{display:flex;gap:8px;margin-top:22px;flex-wrap:wrap}@media(max-width:1200px){.workspace{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.shell{display:block}.sidebar{padding:16px;gap:12px;border-bottom:1px solid #e3e9f1}.sidebar .account,.sidebar .caption{display:none}.main{padding:24px 16px}.topbar{margin-bottom:24px}.panel{padding:16px}.stats{gap:10px}.stat{padding:16px}h1{font-size:27px}}
