<div class="workspace"><section class="panel"><h2>Categorías</h2><p class="muted">Consulta, edita y controla su disponibilidad.</p><form class="filters" method="GET" action="{{ route('admin.categories.index') }}"><input type="search" name="search" value="{{ $search }}" placeholder="Buscar categoría…" aria-label="Buscar categoría" maxlength="100"><select name="status" aria-label="Filtrar por estado"><option value="">Todos los estados</option><option value="active" @selected($status === 'active')>Activas</option><option value="inactive" @selected($status === 'inactive')>Inactivas</option></select><button>Filtrar</button>@if($search || $status)<a class="button" href="{{ route('admin.categories.index') }}">Limpiar</a>@endif</form>
<div class="table-wrap"><table><thead><tr><th scope="col">Categoría</th><th scope="col">Proyectos</th><th scope="col">Estado</th><th scope="col">Acciones</th></tr></thead><tbody>@forelse($categories as $category)<tr><td><strong>{{ $category->name }}</strong><small>{{ $category->slug }}</small>@if($category->description)<small>{{ \Illuminate\Support\Str::limit($category->description, 90) }}</small>@endif</td><td>{{ $category->projects_count }}</td><td><span class="badge {{ $category->is_active ? '' : 'inactive' }}">{{ $category->is_active ? 'Activa' : 'Inactiva' }}</span></td><td><div class="actions"><a href="{{ route('admin.categories.index', ['edit' => $category->id]) }}#category-form" aria-label="Editar {{ $category->name }}">Editar</a><form method="POST" action="{{ route('admin.categories.status', $category) }}" onsubmit="return confirm(this.dataset.confirm)" data-confirm="{{ $category->is_active ? '¿Desactivar esta categoría? Los proyectos existentes se conservarán.' : '¿Reactivar esta categoría para nuevas publicaciones?' }}">@csrf @method('PATCH')<input type="hidden" name="is_active" value="{{ $category->is_active ? 0 : 1 }}"><button aria-label="{{ $category->is_active ? 'Desactivar' : 'Reactivar' }} {{ $category->name }}">{{ $category->is_active ? 'Desactivar' : 'Reactivar' }}</button></form></div></td></tr>@empty<tr><td colspan="4" class="empty">No hay categorías que mostrar. Crea una o ajusta los filtros.</td></tr>@endforelse</tbody></table></div>
<nav class="pagination" aria-label="Paginación de categorías"><span>{{ $categories->total() }} resultados · Página {{ $categories->currentPage() }} de {{ $categories->lastPage() }}</span><div>@if($categories->previousPageUrl())<a class="button" href="{{ $categories->previousPageUrl() }}">Anterior</a>@endif @if($categories->nextPageUrl())<a class="button" href="{{ $categories->nextPageUrl() }}">Siguiente</a>@endif</div></nav></section>
<section class="panel" id="category-form"><h2>{{ $editing ? 'Editar categoría' : 'Nueva categoría' }}</h2><p class="muted">{{ $editing ? 'Actualiza los datos de esta categoría.' : 'Abre espacio para nuevas iniciativas.' }}</p><form method="POST" action="{{ $editing ? route('admin.categories.update', $editing) : route('admin.categories.store') }}">@csrf @if($editing) @method('PUT') @endif<label for="name">Nombre</label><input id="name" name="name" required maxlength="100" value="{{ old('name', $editing?->name) }}" placeholder="Ej. Desarrollo de software"><label for="slug">Slug único</label><input id="slug" name="slug" required maxlength="100" pattern="[a-z0-9]+(-[a-z0-9]+)*" value="{{ old('slug', $editing?->slug) }}" placeholder="desarrollo-de-software" aria-describedby="slug-help"><small id="slug-help">Minúsculas, números y guiones.</small><label for="description">Descripción <small>(opcional)</small></label><textarea id="description" name="description" rows="4" maxlength="1000" placeholder="¿Qué proyectos pertenecen aquí?">{{ old('description', $editing?->description) }}</textarea><div class="form-actions"><button class="primary">{{ $editing ? 'Guardar cambios' : 'Crear categoría' }}</button>@if($editing)<a class="button" href="{{ route('admin.categories.index') }}">Cancelar</a>@endif</div></form><div class="helper">Las categorías inactivas dejan de aparecer en las nuevas selecciones. Los proyectos que ya las utilizan conservan su información.</div></section></div>
